INSERT INTO public.mock_tests (id, title, description, exam_type, module, difficulty, duration_minutes, is_premium, created_at, updated_at) VALUES ('589b5554-8c7a-4204-a675-80016e65f1e3', 'TEF Expression Écrite - Nouveaux Horizons', 'Examen de pratique TEF intermédiaire.', 'tef', 'writing', 'intermediate', 60, True, '2026-07-30T01:04:30.294923', '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('4a186df1-9b31-41b0-bb2d-040e2fbac533', '589b5554-8c7a-4204-a675-80016e65f1e3', '### Section A : Fait divers\n\nVous avez lu dans un journal local qu''un chat a sauvé son maître d''un incendie. Rédigez un court article pour relater cet événement (80 mots minimum).', 10, 0, '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('ef996e57-277a-447e-9d8b-d2e95c10027a', '589b5554-8c7a-4204-a675-80016e65f1e3', '### Section B : Lettre d''argumentation\n\nLe parc de votre quartier va être transformé en parking. Vous écrivez au journal de la ville pour exprimer votre mécontentement et expliquer pourquoi il est important de préserver les espaces verts (200 mots minimum).', 20, 1, '2026-07-30T01:04:30.294923');
INSERT INTO public.mock_tests (id, title, description, exam_type, module, difficulty, duration_minutes, is_premium, created_at, updated_at) VALUES ('bb5a47fa-ff5b-4b92-9ce1-266bbf3f2215', 'TEF Expression Écrite - Engagement Social', 'Examen de pratique TEF intermédiaire.', 'tef', 'writing', 'intermediate', 60, True, '2026-07-30T01:04:30.294923', '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('5b094b1f-d354-4bea-9f4f-b1a733ecc01f', 'bb5a47fa-ff5b-4b92-9ce1-266bbf3f2215', '### Section A : Fait divers\n\nUn groupe de jeunes a organisé un nettoyage géant de la plage locale. Rédigez un court article pour le journal de l''école (80 mots minimum).', 10, 0, '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('1cc37bfb-c221-4f54-8ad9-ffbaeb6327eb', 'bb5a47fa-ff5b-4b92-9ce1-266bbf3f2215', '### Section B : Lettre d''argumentation\n\nVotre entreprise veut supprimer le télétravail. Écrivez une lettre à votre directeur pour argumenter en faveur du maintien du travail à distance, en mettant en avant la productivité et le bien-être des employés (200 mots minimum).', 20, 1, '2026-07-30T01:04:30.294923');
INSERT INTO public.mock_tests (id, title, description, exam_type, module, difficulty, duration_minutes, is_premium, created_at, updated_at) VALUES ('9f3769df-3be7-44b7-b63d-302b86fc4f98', 'TEF Expression Orale - Loisirs et Culture', 'Examen de pratique TEF intermédiaire.', 'tef', 'speaking', 'intermediate', 15, True, '2026-07-30T01:04:30.294923', '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('67ad396d-0d98-4bb4-9fc3-f01303865dd3', '9f3769df-3be7-44b7-b63d-302b86fc4f98', '### Section A : S''informer sur un service\n\nVous voulez vous inscrire à un club de photographie. Appelez le responsable pour obtenir des informations sur les activités, le matériel requis et les tarifs.', 10, 0, '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('ad4edada-27aa-4175-91fa-83c5a9d88d88', '9f3769df-3be7-44b7-b63d-302b86fc4f98', '### Section B : Convaincre un proche\n\nUn ami refuse d''aller au musée d''art moderne car il trouve cela ennuyeux. Essayez de le convaincre de vous accompagner en lui présentant une exposition particulière.', 20, 1, '2026-07-30T01:04:30.294923');
INSERT INTO public.mock_tests (id, title, description, exam_type, module, difficulty, duration_minutes, is_premium, created_at, updated_at) VALUES ('fe9f874d-ab9f-4678-a666-9899c9d200a9', 'TEF Expression Orale - Environnement et Futur', 'Examen de pratique TEF intermédiaire.', 'tef', 'speaking', 'intermediate', 15, True, '2026-07-30T01:04:30.294923', '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('390a1a8b-f662-43b6-a3e7-36682764e478', 'fe9f874d-ab9f-4678-a666-9899c9d200a9', '### Section A : S''informer sur un service\n\nVous êtes intéressé par l''achat d''un vélo électrique. Appelez un magasin spécialisé pour poser des questions sur l''autonomie, la garantie et les aides financières disponibles.', 10, 0, '2026-07-30T01:04:30.294923');
INSERT INTO public.test_questions (id, test_id, question_text, points, order_index, created_at) VALUES ('39e633cf-1c9f-4f35-931c-365b003a0e49', 'fe9f874d-ab9f-4678-a666-9899c9d200a9', '### Section B : Convaincre un proche\n\nVotre frère utilise encore beaucoup de sacs en plastique. Essayez de le convaincre d''adopter des habitudes plus écologiques au quotidien.', 20, 1, '2026-07-30T01:04:30.294923');
